// Reads the uploaded .md / .txt file as UTF-8 text.
const item = $input.first();
const keys = Object.keys(item.binary || {});
if (!keys.length) throw new Error('No file was uploaded.');
const buf = await this.helpers.getBinaryDataBuffer(0, keys[0]);
return [{ json: { ...item.json, stories_text: buf.toString('utf8'), file_name: item.binary[keys[0]].fileName || '' } }];

// Splits the uploaded story file into one item per story and drops duplicates of rows already in the sheet.
// Accepts "## 23. HEADLINE", "## 23 — HEADLINE", "## QDE-FC-49 — HEADLINE", "23) HEADLINE", "23: HEADLINE", "1. HEADLINE — pitch".
// v1.7 (2026-10-03): each story may carry a BART PERSPECTIVE section (Bart's own account, used by the copy step only)
// and a RESEARCH section (Bart's research notes, passed to deep research as leads). Repeated headings for the same
// story are merged.
// Guardrails (2026-10-02): titles must be ALL CAPS; label lines are never stories; more than MAX_STORIES writes NOTHING.
const MAX_STORIES = 15;
const cfg = $('Config').first().json;
let raw = String(cfg.stories_text || '').replace(/\r/g, '').replace(/\u00a0/g, ' ')
  .replace(/!\[[^\]]*\]\([^)]*\)(\{[^}]*\})?/g, '')
  .replace(/\\([\\`*_{}\[\]()#+\-.!'"$|])/g, '$1')
  .replace(/[ \t]*\\$/gm, '')
  .replace(/^\s*[-_*]{3,}\s*$/gm, '');
const rows = $('Read queue').all().map(r => r.json).filter(r => r && r.post_id);
let maxNum = 0;
for (const r of rows) { const m = String(r.post_id).match(/QDE-FC-(\d+)/i); if (m) maxNum = Math.max(maxNum, +m[1]); }
const norm = s => String(s || '').toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
const existingKeys = new Set(rows.flatMap(r => [norm(r.title), norm(r.headline)]).filter(Boolean));
const existingList = rows.map(r => `${r.post_id}: ${r.title || ''} | ${r.headline || ''}`).join('\n');

const NUM = /^[ \t]*#{0,6}[ \t]*\*{0,2}[ \t]*(?:QDE-FC-)?\d{1,3}\*{0,2}[ \t]*(?:[.):]|[—–]|-{1,3})[ \t]+/m;
const NUM_G = new RegExp(NUM.source, 'm');
const fail = (msg) => [{ json: { none: true, skipped: [msg], next_num: maxNum + 1 } }];
if (!NUM.test(raw)) return fail('File format not recognized: no numbered story headings found (expected lines like "## 31. HEADLINE" or "## QDE-FC-49 — HEADLINE"). Nothing was written.');
let blocks = raw.split(NUM_G).slice(1);
// Drop any trailing top-level section that is not a numbered story (e.g. "# Closest calls"). Sub-headings (###) stay.
blocks = blocks.map(b => b.split(/\n[ \t]*#{1,2}[ \t]+(?!\d|QDE-FC-)/)[0]);
// A numbered line whose text is not an ALL-CAPS headline (a numbered list inside a story's notes) is not a new story:
// glue it back onto the story above it.
{
  const headOk = b => { const f = String(b.split('\n')[0] || '').replace(/\*\*|__/g, '').trim().split(/\s+(?:[—–]|-{1,3})\s+/)[0];
    const L = f.replace(/[^A-Za-z]/g, ''); return L.length >= 4 && L.replace(/[^A-Z]/g, '').length / L.length > 0.8; };
  const merged = [];
  for (const b of blocks) { if (merged.length && !headOk(b)) merged[merged.length - 1] += '\n' + b; else merged.push(b); }
  blocks = merged;
}

const PERSP = /^[ \t*_#]*BART'?S?\b[^\n]{0,25}PERS?P\w*CTIVE[^\n]*$/im;
const RESR = /^[ \t*_#]*(?:CHAT ?GPT )?(?:DEEP )?RESEARCH(?: NOTES)?[ \t*_:]*$/im;
function sections(b) {
  const marks = [];
  const scan = (re, kind) => { const g = new RegExp(re.source, 'gim'); let m; while ((m = g.exec(b))) marks.push({ i: m.index, end: m.index + m[0].length, kind }); };
  scan(PERSP, 'persp'); scan(RESR, 'research');
  marks.sort((a, z) => a.i - z.i);
  const out = { main: b, persp: '', research: '' };
  if (!marks.length) return out;
  out.main = b.slice(0, marks[0].i);
  marks.forEach((m, k) => { const txt = b.slice(m.end, k + 1 < marks.length ? marks[k + 1].i : b.length); out[m.kind] += '\n' + txt; });
  return out;
}
const cleanTranscript = s => String(s || '').split('\n')
  .filter(l => !/^\s*(\*\*)?SPEAKERS(\*\*)?\s*$/i.test(l) && !/^\s*\d{1,2}:\d{2}(:\d{2})?\s*$/.test(l)
    && !/^\s*(Mon|Tue|Wed|Thu|Fri|Sat|Sun),? \w{3} \d{1,2}, \d{4}/.test(l) && !/^\s*\*{0,2}Bart Baggett\*{0,2}\s*$/.test(l))
  .map(l => l.replace(/^\s*\*{0,2}Bart Baggett\*{0,2}\s+\d{1,2}:\d{2}\s*/, '').replace(/[*_]{1,3}/g, ''))
  .join('\n').replace(/\n{3,}/g, '\n\n').trim();

const clean = s => String(s || '').replace(/\*\*|__/g, '').replace(/^#{1,6}\s*/gm, '').replace(/\s+/g, ' ').trim();
const isCaps = s => { const L = s.replace(/[^A-Za-z]/g, ''); return L.length >= 4 && L.replace(/[^A-Z]/g, '').length / L.length > 0.8; };
const LABEL = /^(visual|lead source|lead|verify next|bart connection|research status|research lead|facts?|sources?|limits|notes?|editorial|score|three beats)\b[^:]{0,20}:/i;
const DASH = /\s+(?:[—–]|-{1,3})\s+/;
const byKey = new Map(), skipped = [];
let lastKey = '';
blocks.forEach((b0, i) => {
  const sec = sections(b0);
  const b = sec.main;
  const lines = b.split('\n').map(l => l.trim()).filter(Boolean);
  if (!lines.length) return;
  let title = '', second = '', pitch = '';
  const first = clean(lines[0]);
  const second0 = lines.length > 1 ? clean(lines[1]).split(DASH)[0] : '';
  if (lines.length > 1 && isCaps(first.split(DASH)[0]) && !isCaps(second0)) {
    const segs = first.split(DASH);
    title = segs[0].replace(/\s*(?:[—–]|-{1,3})\s*$/, '').trim();
    if (segs[1] && isCaps(segs[1])) second = segs[1].trim();
    pitch = clean([segs.slice(second ? 2 : 1).join(' — '), ...lines.slice(1)].join('\n'));
  } else {
    const segs = clean(b).split(DASH);
    title = (segs[0] || '').trim();
    let rest = segs.slice(1);
    if (rest.length && isCaps(rest[0])) { second = rest[0].trim(); rest = rest.slice(1); }
    pitch = rest.join(' — ').trim();
  }
  const INC = /\s*[(\[](?:INCLUDE|INCLUDED|APPROVED)[)\]]\s*/gi;
  const approved = INC.test(title + ' ' + pitch);
  title = title.replace(INC, ' ').replace(/^["“]|["”]$/g, '').trim(); pitch = pitch.replace(INC, ' ').trim();
  if ((title + pitch).length < 30) return;
  if ((LABEL.test(title) || !isCaps(title)) && lastKey && byKey.has(lastKey)) { const o = byKey.get(lastKey).json; o.bart_research = (o.bart_research ? o.bart_research + '\n\n' : '') + b0.trim(); return; }
  if (LABEL.test(title) || !isCaps(title)) { skipped.push(`Block ${i + 1} skipped: no ALL-CAPS headline ("${title.slice(0, 60)}")`); return; }
  const key = norm(title);
  lastKey = key;
  if (existingKeys.has(key)) { skipped.push(`${title} (already in sheet)`); return; }
  const persp = cleanTranscript(sec.persp);
  const research = String(sec.research || '').trim();
  if (byKey.has(key)) {
    // Same story repeated in the file: merge the extra perspective / research / pitch into the first copy.
    const o = byKey.get(key).json;
    if (persp) o.perspective = (o.perspective ? o.perspective + '\n\n' : '') + persp;
    if (research) o.bart_research = (o.bart_research ? o.bart_research + '\n\n' : '') + research;
    if (pitch && !o.pitch.includes(pitch.slice(0, 80))) o.pitch += ' ' + pitch;
    if (approved) o.approved = true;
    return;
  }
  byKey.set(key, { json: { n: i + 1, approved, rick_title: title, rick_second: second, pitch, perspective: persp, bart_research: research, existing_list: existingList, next_num: maxNum + 1 } });
});
const out = [...byKey.values()];
out.forEach(o => { o.json.perspective = o.json.perspective.slice(0, 8000); o.json.bart_research = o.json.bart_research.slice(0, 20000); });
if (out.length > MAX_STORIES) return fail(`Upload stopped: ${out.length} stories detected, more than the ${MAX_STORIES} allowed per file. The file format was probably misread. Nothing was written.`);
if (!out.length) return [{ json: { none: true, skipped, next_num: maxNum + 1 } }];
out.forEach(o => o.json.pre_skipped = skipped);
return out;

// v1.7 deep research: one Responses API call per story, gpt-5.5 (Config.research_model) with web search, reasoning high.
// Rules come from GitHub: QDE_FamousCase_Research_Prompt_v4.md (document hunt, dossier, Bart connection).
const cfg = $('Config').first().json;
const researchMd = $('Fetch research prompt').first().json.research_md || '';
const s = $json;
const override = s.approved ? `\n\nBART HAS PRE-APPROVED THIS STORY (marked INCLUDE). Your decision MUST be ACCEPT. Write every gate concern as a \u26a0\ufe0f line in fact_status instead, and still research it fully.` : '';
const instructions = `You are the deep-research step of an automated n8n run for Bart Baggett's QDE famous-case post queue. Follow QDE_FamousCase_Research_Prompt_v4 below.

AUTOMATED-RUN OVERRIDES (these win over the file where they differ):
1. The candidate is already chosen by Bart. Do not search for other candidates. Run the five gates, the dedupe against the existing rows listed in the input, the full §2 document hunt (all tiers A–G), the §3 Bart connection search, the §4 upgrade check, and §5.
2. Be thorough: at least 12 web searches, opening primary records (dockets, opinions, government releases, museum and archive records, the document scan itself, book source notes). Bart's research notes and every URL in them are LEADS — open them and confirm before using. Cite only URLs you opened in this session. Never write a fact from memory.
3. If the title and pitch do not describe ONE identifiable case, decision is REJECT with reason "not a single identifiable case" — never substitute a different case. If a gate fails or the case duplicates an existing row, REJECT and say which gate and why in one sentence.
4. Do NOT write a headline, caption or image prompt.
5. Bart's personal account (BART PERSPECTIVE) is context only. Never cite it as a source and never put his private memories in fact_status; a PUBLIC mention of Bart (book, article, court paper) goes on the BART CONNECTION line with what it does and does not establish.
6. A person charged but not convicted: "accused"/"charged", never guilty, plus a \u26a0\ufe0f PENDING CASE line. A court admitting a will, dismissing on standing or excluding evidence is NOT a finding that a signature is genuine — say exactly what happened.
7. If sources are thin but the gates pass, still ACCEPT with facts_need_verify YES and \u26a0\ufe0f lines.
8. Output ONLY one JSON object, no prose, no code fence, with exactly these keys:
{
 "decision": "ACCEPT" or "REJECT",
 "reject_reason": "" or one sentence naming the failed gate,
 "duplicate_of": "" or the existing post_id,
 "title": "case name for humans",
 "beat": "one beat from the rotation list",
 "torn_note": "3 to 4 short fragments separated by ' · '",
 "face_source": "the SCENE brief (who is in frame and how to describe them, or why nobody is; period, setting, props; the real document if a scan exists). Positive statements only.",
 "facts_need_verify": "YES" if any \u26a0\ufe0f line remains, else "NO",
 "fact_status": "the §5 fact card, max ~2,500 characters, ending with SOURCES (one opened URL per line with what it supports, primary records first) and then every \u26a0\ufe0f line",
 "bart_connection": "every public mention of Bart Baggett tied to this case with source, or 'none found'",
 "upgrade": "a stronger sourced angle on the same case, or ''",
 "exhibits": [{"url": "direct URL to a PDF, image, docket entry, opinion or record", "type": "pdf|image|docket|opinion|release|record|page", "what": "what it shows, with page numbers"}],
 "dossier_md": "the full §5 dossier in Markdown: tier-by-tier findings (A–G, 'searched, nothing found' where empty), exhibit list, quotable lines with sources, Bart connection, upgrade, open questions, best visuals",
 "sources": [{"url": "...", "supports": "..."}]
}

===== QDE_FamousCase_Research_Prompt (current version from GitHub) =====
${researchMd}${override}`;
const input = `STORY FROM BART:
Title: ${s.rick_title}
${s.rick_second ? 'Second line: ' + s.rick_second + '\n' : ''}Pitch and story card: ${s.pitch}
${s.bart_research ? '\nBART\'S RESEARCH NOTES (leads to open and verify, not sources):\n' + s.bart_research + '\n' : ''}${s.perspective ? '\nBART PERSPECTIVE (his private account — context only, never a source):\n' + s.perspective.slice(0, 3000) + '\n' : ''}
EXISTING ROWS IN QDE_Post_Queue (post_id: title | headline):
${s.existing_list}`;
const body = /deep-research/.test(cfg.research_model)
  ? { model: cfg.research_model, instructions, input, tools: [{ type: 'web_search_preview' }] }
  : { model: cfg.research_model, instructions, input, tools: [{ type: 'web_search', search_context_size: 'high' }],
      include: ['web_search_call.action.sources'], reasoning: { effort: cfg.research_effort || 'high' } };
return { json: { ...s, body } };

// v1.7: pull the model's JSON out of the Responses output; keep only source URLs the model actually retrieved.
const s = $('Build research request').item.json;
const r = $json;
const retrieved = new Set();
let text = '', searches = 0;
for (const o of (r.output || [])) {
  if (o.type === 'web_search_call') { searches++; const a = o.action || {}; for (const x of (a.sources || [])) if (x.url) retrieved.add(x.url); if (a.url) retrieved.add(a.url); }
  if (o.type === 'message') for (const c of (o.content || [])) if (c.type === 'output_text') { text += c.text; for (const a of (c.annotations || [])) if (a.url) retrieved.add(a.url); }
}
const normU = u => String(u || '').replace(/[?#].*$/, '').replace(/\/$/, '').replace(/^https?:\/\/(www\.)?/, '').toLowerCase();
const rset = new Set([...retrieved].map(normU));
const isRet = u => rset.has(normU(u));
const base = { n: s.n, approved: !!s.approved, rick_title: s.rick_title, rick_second: s.rick_second, pitch: s.pitch, perspective: s.perspective || '', next_num: s.next_num, pre_skipped: s.pre_skipped || [] };
let d = null, err = '';
if (r.error) err = 'OpenAI error: ' + (r.error.message || JSON.stringify(r.error)).slice(0, 300);
else if (!text) err = 'OpenAI returned no text (status ' + (r.status || '?') + ')';
else { const m = text.replace(/```json|```/g, '').match(/\{[\s\S]*\}/); try { d = JSON.parse(m ? m[0] : text); } catch (e) { err = 'Could not parse research JSON'; } }
if (!d) return { json: { ...base, decision: 'ERROR', reject_reason: err } };
if (!/^(ACCEPT|REJECT)$/.test(d.decision)) d.decision = 'REJECT';
if (s.approved && d.decision !== 'ACCEPT') { d.fact_status = String(d.fact_status || '') + `\n\u26a0\ufe0f Bart pre-approved this story (INCLUDE). Research would have rejected it: ${d.reject_reason || 'no reason given'}`; d.decision = 'ACCEPT'; d.reject_reason = ''; }
// Strip any URL in the fact card that was not retrieved in this session (the 2026-10-02 rows carried invented links).
const dropped = [];
let fs = String(d.fact_status || '').split('\n').map(line => {
  const urls = line.match(/https?:\/\/[^\s,)]+/g); if (!urls) return line;
  let l = line; for (const u of urls) if (!isRet(u.replace(/[.;]+$/, ''))) { dropped.push(u); l = l.replace(u, ''); }
  if (l === line) return line;
  if (!/https?:\/\//.test(l)) return /^\s*SOURCES:/i.test(l) ? 'SOURCES:' : null;
  return l.trim();
}).filter(l => l !== null).join('\n');
const good = [...new Set((fs.match(/https?:\/\/[^\s,)]+/g) || []).map(normU))];
if (d.decision === 'ACCEPT' && good.length < 2) fs += `\n\u26a0\ufe0f Only ${good.length} retrieved source URL(s) in the fact card — verify every fact before READY.`;
if (dropped.length) fs += `\n\u26a0\ufe0f Removed ${dropped.length} cited URL(s) the research model did not actually open.`;
if (d.bart_connection && !/none found/i.test(d.bart_connection) && !/BART CONNECTION/i.test(fs)) fs = fs.replace(/\nSOURCES:/, `\nBART CONNECTION: ${d.bart_connection}\nSOURCES:`);
d.fact_status = fs;
if (/\u26a0/.test(fs)) d.facts_need_verify = 'YES';
const exhibits = (Array.isArray(d.exhibits) ? d.exhibits : []).filter(x => x && /^https?:\/\//.test(x.url || '')).map(x => ({ ...x, opened: isRet(x.url) }));
return { json: { ...base, ...d, exhibits, _searches: searches, _retrieved: good.length } };

// Stage B copy (and gold word / sub-line) from GitHub: Story Prompt V5 + Headline rules + names + voice + Bart perspectives.
const cfg = $('Config').first().json;
const story = $('Fetch story prompt').first().json.story_md || '';
const head = $('Fetch headline rules').first().json.headline_md || '';
const names = $('Fetch names file').first().json.names_md || '';
const voice = $('Fetch Bart voice').first().json.voice_md || '';
const persp = $('Fetch Bart perspectives').first().json.perspectives_md || '';
const d = $json;
const narrative = String(d.fact_status || '').split(/\n?\s*\u26a0\ufe0f/)[0].trim();
const sys = `You are Peggy, the copywriter, running inside an automated n8n workflow for the QDE famous-case post queue.

AUTOMATED-RUN OVERRIDES (these win over the files where they differ):
1. Stage A is DONE. Bart already ran RICK. The headline is supplied. Column D = the supplied headline, verbatim, in ALL CAPS. Only correct the spelling of a proper noun or accent. Never reword, shorten or lengthen it.
2. YOU write, following the rules in Headline-QDE-Post.md:
   - gold_word: 1 to 3 words that appear VERBATIM in the headline. Prefer the concrete noun or crime word.
   - subline: the second shock, two short beats, under twelve words, supported by the facts. If Bart supplied a second RICK line, use it as the basis when the facts support it.
3. Then write Stage B of QDE_FamousCase_Story_Prompt_V5.md exactly: image_prompt (B1 house shape; quote the headline and gold word exactly as in D and E; quote the torn-note fragments verbatim and state the count; subject from face_source; positive statements only, no negation words outside quotation marks) and caption (B2: under 200 words before the CTA, five parts, Bart's first-person paragraph per V5 part 4, the exact CTA block, then exactly five hashtags on one line).
4. Never state or imply that a living person committed a crime unless the narrative says they were convicted; for a pending case write \"charged\" or \"accused\" in the sub-line, image prompt and caption. Use ONLY facts in the sourced narrative supplied. Never use anything from the warning lines. Never invent a fact, a quote or a Bart opinion.
5. BART'S PARAGRAPH (V5 part 4). If a BART PERSPECTIVE is supplied below, or BART_FORENSIC_PERSPECTIVES.md has a case note for this story, open Bart's paragraph with his real connection or view in plain words (one or two sentences), then the forensic lesson. If the two disagree, the BART_FORENSIC_PERSPECTIVES.md case note wins (it has Bart's confirmed corrections). Never say or imply Bart examined an original, authenticated, was retained or testified unless that text says so; a look at a published copy is "looking at the published copy" and is never an official opinion. Otherwise open with "I wasn't involved in the ___ case."
6. A public BART CONNECTION in the narrative (a book, article or court paper naming Bart) may be used as a fact.
7. Return ONLY a JSON object with keys: headline, gold_word, subline, image_prompt, caption.

===== QDE_FamousCase_Story_Prompt_V5.md =====
${story}

===== Headline-QDE-Post.md =====
${head}

===== Peggy_Copy_Names_and_Spelling_v1.md =====
${names}

===== BART_BAGGETT_VOICE.MD =====
${voice}

===== BART_FORENSIC_PERSPECTIVES.md =====
${persp}`;
const user = `SUPPLIED HEADLINE (RICK): ${d.rick_title}
${d.rick_second ? 'SUPPLIED SECOND LINE (RICK): ' + d.rick_second + '\n' : ''}CASE (column B): ${d.title}
TORN NOTE (column G): ${d.torn_note}
SCENE (column H): ${d.face_source}
SOURCED NARRATIVE (from column N, warnings removed):
${narrative}
${d.perspective ? '\nBART PERSPECTIVE (his own account from the story file — for his paragraph only):\n' + String(d.perspective).slice(0, 4000) : '\nBART PERSPECTIVE: none supplied in the story file (check BART_FORENSIC_PERSPECTIVES.md for a case note).'}`;
const cm = cfg.copy_model || cfg.model;
const body = { model: cm, response_format: { type: 'json_object' }, messages: [{ role: 'system', content: sys }, { role: 'user', content: user }] };
if (/^(gpt-5|o\d)/.test(cm)) body.reasoning_effort = 'medium'; else body.temperature = 0.4;
return { json: { ...d, body } };

// Completeness gate (Story Prompt V4) — repair or flag, never block. Assigns post_ids in story order.
const cfg = $('Config').first().json;
const reqs = $('Build copy request').all().map(i => i.json);
const outs = $input.all().map(i => i.json);
const stamp = $now.setZone('America/Chicago').toFormat('yyyy-LL-dd HH:mm');
const words = s => String(s || '').trim().split(/\s+/).filter(Boolean).length;
const pairs = reqs.map((d, i) => ({ d, o: outs[i] })).sort((a, b) => a.d.n - b.d.n);
let num = reqs.length ? reqs[0].next_num : 1;
const rows = [];
// Final duplicate guard: never append a row whose headline or case title already exists in the sheet or earlier in this batch.
const normK = s => String(s || '').toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
const seen = new Set($('Read queue').all().map(r => r.json).flatMap(r => [normK(r.title), normK(r.headline)]).filter(Boolean));
const dups = [];
for (const { d, o } of pairs) {
  const flags = [];
  let c = {};
  try { c = JSON.parse(o.choices[0].message.content); } catch (e) { flags.push('COPY NOT WRITTEN (OpenAI error)'); }
  let headline = String(c.headline || d.rick_title || '').toUpperCase().replace(/\s+/g, ' ').trim();
  const gold = String(c.gold_word || '').toUpperCase().trim();
  const subline = String(c.subline || '').trim();
  const J = String(c.image_prompt || '').trim();
  const L = String(c.caption || '').trim();
  const G = String(d.torn_note || '').trim();
  const H = String(d.face_source || '').trim();
  if (headline !== String(d.rick_title).toUpperCase().replace(/\s+/g, ' ').trim()) flags.push('HEADLINE CHANGED FROM RICK TEXT — check D');
  for (const [k, v] of Object.entries({ headline, gold_word: gold, subline, torn_note: G, face_source: H, image_prompt: J, caption: L })) if (!v) flags.push(`EMPTY ${k}`);
  if (words(headline) > 8) flags.push(`HEADLINE ${words(headline)} WORDS (max 8)`);
  if (gold && !headline.includes(gold)) flags.push('GOLD WORD NOT IN HEADLINE');
  if (words(gold) > 3) flags.push('GOLD WORD OVER 3 WORDS');
  if (words(subline) >= 12) flags.push(`SUBLINE ${words(subline)} WORDS (under 12)`);
  const frags = G.split('·').map(s => s.trim()).filter(Boolean).length;
  if (frags < 3 || frags > 4) flags.push(`TORN NOTE HAS ${frags} FRAGMENTS (3–4)`);
  if (J && !J.toUpperCase().includes(headline)) flags.push('IMAGE PROMPT DOES NOT QUOTE HEADLINE');
  if (J && gold && !J.toUpperCase().includes(gold)) flags.push('IMAGE PROMPT MISSING GOLD WORD');
  if (/\[\[|\]\]/.test(J + L)) flags.push('PLACEHOLDER BRACKETS');
  const unquoted = J.replace(/"[^"]*"|“[^”]*”/g, '');
  if (/\b(no|not|without|remove)\b/i.test(unquoted)) flags.push('NEGATION IN IMAGE PROMPT');
  const cta = '1-800-980-9030';
  const ci = L.indexOf(cta);
  if (ci < 0) flags.push('CTA MISSING');
  else {
    if (words(L.slice(0, ci)) >= 200) flags.push(`CAPTION ${words(L.slice(0, ci))} WORDS (under 200)`);
    if (!/1-800-980-9030\s*\n\s*HandwritingExpertUSA\.com · bartbaggett\.com/.test(L)) flags.push('CTA BLOCK NOT EXACT');
  }
  const tags = (L.match(/(^|\s)#[A-Za-z0-9_]+/g) || []).length;
  if (tags !== 5) flags.push(`${tags} HASHTAGS (need 5)`);
  if (!/I wasn[’']t involved in the /.test(L)) {
    if (!d.perspective) flags.push('MISSING "I wasn\'t involved" LINE');
    else if (!/(^|\s)(I|I'm|I’m|me|my)\s/.test(L)) flags.push('BART PARAGRAPH MISSING');
  }
  if (/\bI (authenticated|examined the original|testified|was hired|was retained)\b/i.test(L)) flags.push('CHECK: caption says Bart examined/testified/was hired');
  if (/official opinion/i.test(L) && !/not an official opinion/i.test(L)) flags.push('CHECK: "official opinion" wording');
  if (/handwritingexpert\.com/i.test(L)) flags.push('BANNED DOMAIN HandwritingExpert.com');
  if (/grapholog/i.test(L.replace(/#\S+/g, ''))) flags.push('GRAPHOLOGY IN BODY');
  if (L.includes('!')) flags.push('EXCLAMATION MARK');
  const kH = normK(headline), kT = normK(d.title || d.rick_title);
  if (seen.has(kH) || seen.has(kT)) { dups.push(`${headline} (duplicate of an existing row)`); continue; }
  seen.add(kH); seen.add(kT);
  rows.push({
    post_id: `QDE-FC-${num++}`, title: d.title || d.rick_title, status: '',
    headline, gold_word: gold, subline, torn_note: G, face_source: H, photo_required: '',
    image_prompt: J, image_url: '', caption: L,
    facts_need_verify: d.facts_need_verify === 'NO' ? 'NO' : 'YES',
    fact_status: String(d.fact_status || ''),
    notes: `INTAKE ${stamp} (${cfg.submitted_by}) via Peggy story form v1.7 (deep research ${cfg.research_model}, ${d._searches || 0} searches, ${d._retrieved || 0} sources)${d.perspective ? ' · Bart perspective used' : ''} | Flags: ${flags.join('; ') || 'none'}`,
    _exhibits: d.exhibits || [], _dossier: d.dossier_md || '', _bart_connection: d.bart_connection || '', _upgrade: d.upgrade || '', _perspective: d.perspective || ''
  });
}
return rows.map(r => ({ json: { ...r, _dups: dups } }));

// Slack note for Katie: what was added, what was rejected, and her one job — type READY in column C.
const pick = n => { try { return $(n).all().map(i => i.json); } catch (e) { return []; } };
let added = pick('Attach evidence link').filter(r => r.post_id);
if (!added.length) added = pick('Gate + build rows').filter(r => r.post_id);
const gateDups = (added[0] && added[0]._dups) || [];
const parsed = pick('Parse research');
const split = pick('Split stories');
const pre = [...((split[0] && split[0].pre_skipped) || (split[0] && split[0].skipped) || []), ...gateDups];
const rejected = parsed.filter(p => p.decision !== 'ACCEPT');
const cfg = $('Config').first().json;
const sheet = 'https://docs.google.com/spreadsheets/d/' + cfg.sheet_id + '/edit#gid=0';
const lines = [];
if (added.length) {
  const first = added[0].post_id, last = added[added.length - 1].post_id;
  lines.push(`<@${cfg.ready_owner_slack_id}> ${added.length} new celebrity case${added.length === 1 ? '' : 's'} (${first}${added.length > 1 ? ' to ' + last : ''}) just landed in QDE_Post_Queue and need your review. Nothing happens with them until you mark them READY in column C. Please review the headline and mark READY to activate the story.`);
  lines.push('');
  lines.push('For each new row:');
  lines.push('1. Review columns D to F (headline, gold word, sub-line) with human eyes.');
  lines.push('2. Check column N (fact_status) for any \u26a0\ufe0f lines, and the flags listed below.');
  lines.push('3. If it is good, type READY in column C (status), all caps, to activate the story.');
  lines.push('4. If it is not usable, leave column C blank and reply in this thread with the post_id and what is wrong.');
  lines.push('');
  for (const r of added) {
    const fl = (r.notes.split('Flags: ')[1] || 'none');
    lines.push(`• ${r.post_id} — ${r.headline} (${r.title}) · facts need verify: ${r.facts_need_verify} · flags: ${fl}`);
    if (r._folder_link) lines.push(`    evidence + dossier: ${r._folder_link}`);
  }
  lines.push('');
  lines.push('Sheet: ' + sheet);
} else {
  lines.push('Peggy story intake finished: no new rows were added to QDE_Post_Queue.');
}
if (rejected.length || pre.length) {
  lines.push('');
  lines.push(`Not added (${rejected.length + pre.length}):`);
  for (const r of rejected) lines.push(`✗ ${r.rick_title} — ${r.decision === 'ERROR' ? 'ERROR: ' : ''}${r.reject_reason || 'rejected'}${r.duplicate_of ? ' (duplicate of ' + r.duplicate_of + ')' : ''}`);
  for (const s of pre) lines.push(`✗ ${s}`);
  lines.push('To include a rejected story anyway, add (INCLUDE) after its headline in the .md file and upload it again.');
}
lines.push('');
lines.push(`Submitted by: ${cfg.submitted_by}`);
return [{ json: { text: lines.join('\n') } }];

// v1.7: put each story's evidence-folder link into its notes before the rows are appended.
const rows = $('Gate + build rows').all().map(i => i.json);
const folders = $('Create evidence folder').all().map(i => i.json);
return rows.map((r, i) => {
  const f = folders[i] || {};
  const id = f.id && !f.error ? f.id : '';
  const link = id ? `https://drive.google.com/drive/folders/${id}` : '';
  const ex = (r._exhibits || []).length;
  return { json: { ...r, _folder_id: id, _folder_link: link,
    notes: r.notes + (link ? ` | Evidence folder (dossier + ${ex} exhibit link(s)): ${link}` : ' | Evidence folder: not created (Drive error)') } };
});

// v1.7: list the downloadable exhibits (PDFs and images) for each new row. Max 8 per story.
const out = [];
for (const it of $input.all()) {
  const r = it.json;
  if (!r._folder_id) continue;
  const seen = new Set();
  let k = 0;
  for (const x of (r._exhibits || [])) {
    const url = String(x.url || '').trim();
    const looksFile = /\.(pdf|jpe?g|png|gif|webp|tiff?)(\?|#|$)/i.test(url) || /^(pdf|image)$/i.test(x.type || '');
    if (!looksFile || seen.has(url) || k >= 8) continue;
    seen.add(url); k++;
    out.push({ json: { post_id: r.post_id, folder_id: r._folder_id, url, what: String(x.what || '').slice(0, 120), base_name: `${r.post_id} exhibit ${k}` } });
  }
}
return out;

// v1.7: keep only real PDFs and images under 25 MB; name them for the evidence folder.
const plan = $('Plan exhibit downloads').all().map(i => i.json);
const out = [];
$input.all().forEach((it, i) => {
  const p = plan[i]; const b = it.binary && it.binary.data;
  if (!p || !b) return;
  const mime = String(b.mimeType || '');
  const size = Number(String(b.fileSize || '0').replace(/[^0-9.]/g, '')) * (/MB/i.test(String(b.fileSize)) ? 1048576 : /kB/i.test(String(b.fileSize)) ? 1024 : 1);
  if (!/^(application\/pdf|image\/)/.test(mime)) return;
  if (size > 25 * 1048576) return;
  const ext = mime === 'application/pdf' ? 'pdf' : (mime.split('/')[1] || 'img').replace('jpeg', 'jpg').replace(/\+.*/, '');
  const safe = p.what.replace(/[^A-Za-z0-9 ,.'-]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 60);
  b.fileName = `${p.base_name}${safe ? ' - ' + safe : ''}.${ext}`;
  out.push({ json: { ...p, file_name: b.fileName }, binary: { data: b } });
});
return out;
